mapper.select:
SELECT feed.workorder_code, feed.task_code, wo.workorder_name, feed.item_code, feed.item_name, feed.specification, feed.unit_of_measure, feed.warehouse_id, feed.warehouse_code, feed.warehouse_name, feed.location_id, feed.location_code, feed.location_name, feed.area_id, feed.area_code, feed.area_name, COALESCE(SUM(feed.quantity), 0) AS actual_quantity, COALESCE(bom.plan_quantity, 0) AS plan_quantity, CASE WHEN bom.plan_quantity > 0 THEN ROUND(COALESCE(SUM(feed.quantity), 0) / bom.plan_quantity * 100, 2) ELSE 0 END AS usage_percentage, MAX(feed.workstation_code) AS workstation_code, MAX(feed.workstation_name) AS workstation_name FROM wms_feed_line feed LEFT JOIN pro_workorder wo ON feed.workorder_code = wo.workorder_code LEFT JOIN ( SELECT workorder_id, item_id, SUM(quantity) AS plan_quantity FROM pro_workorder_bom WHERE deleted = 0 GROUP BY workorder_id, item_id ) bom ON wo.id = bom.workorder_id AND feed.item_id = bom.item_id WHERE feed.deleted = 0 AND wo.deleted = 0 AND bom.plan_quantity > 0
AND feed.workorder_code LIKE CONCAT('%', #{req.workorderCode}, '%')
AND feed.item_code LIKE CONCAT('%', #{req.itemCode}, '%')
AND feed.item_name LIKE CONCAT('%', #{req.itemName}, '%')
AND feed.status = #{req.status}
AND feed.workstation_code = #{req.workstationCode}
AND feed.create_time >= #{req.createTime[0]}
AND feed.create_time <= #{req.createTime[1]}
GROUP BY feed.workorder_code, feed.task_code, wo.workorder_name, feed.item_id, feed.item_code, feed.item_name, feed.specification, feed.unit_of_measure, feed.warehouse_id, feed.warehouse_code, feed.warehouse_name, feed.location_id, feed.location_code, feed.location_name, feed.area_id, feed.area_code, feed.area_name, bom.plan_quantity ORDER BY feed.workorder_code desc, feed.item_code

SELECT -- ROW_NUMBER() OVER (ORDER BY feed.workorder_code DESC, feed.item_code) AS id, CONCAT( feed.workorder_code, '_', feed.item_code, '_', ROW_NUMBER() OVER ( PARTITION BY feed.workorder_code ORDER BY feed.item_code ) ) AS id, ROW_NUMBER() OVER (ORDER BY feed.workorder_code DESC, feed.item_code) AS row_num, feed.workorder_code, feed.task_code, wo.workorder_name, feed.item_code, feed.item_name, feed.specification, feed.unit_of_measure, feed.warehouse_id, feed.warehouse_code, feed.warehouse_name, feed.location_id, feed.location_code, feed.location_name, feed.area_id, feed.area_code, feed.area_name, COALESCE(SUM(feed.quantity), 0) AS actual_quantity, COALESCE(bom.plan_quantity, 0) AS plan_quantity, CASE WHEN bom.plan_quantity > 0 THEN ROUND(COALESCE(SUM(feed.quantity), 0) / bom.plan_quantity * 100, 2) ELSE 0 END AS usage_percentage, MAX(feed.workstation_code) AS workstation_code, MAX(feed.workstation_name) AS workstation_name FROM wms_feed_line feed LEFT JOIN pro_workorder wo ON feed.workorder_code = wo.workorder_code LEFT JOIN ( SELECT workorder_id, item_id, SUM(quantity) AS plan_quantity FROM pro_workorder_bom WHERE deleted = 0 GROUP BY workorder_id, item_id ) bom ON wo.id = bom.workorder_id AND feed.item_id = bom.item_id WHERE feed.deleted = 0 AND wo.deleted = 0 AND bom.plan_quantity > 0
AND feed.workorder_code LIKE CONCAT('%', #{req.workorderCode}, '%')
AND feed.item_code LIKE CONCAT('%', #{req.itemCode}, '%')
AND feed.item_name LIKE CONCAT('%', #{req.itemName}, '%')
AND feed.status = #{req.status}
AND feed.workstation_code = #{req.workstationCode}
AND feed.create_time >= #{req.createTime[0]}
AND feed.create_time <= #{req.createTime[1]}
GROUP BY feed.workorder_code, feed.task_code, wo.workorder_name, feed.item_id, feed.item_code, feed.item_name, feed.specification, feed.unit_of_measure, feed.warehouse_id, feed.warehouse_code, feed.warehouse_name, feed.location_id, feed.location_code, feed.location_name, feed.area_id, feed.area_code, feed.area_name, bom.plan_quantity ORDER BY feed.workorder_code desc, feed.item_code
